import{_ as e,o as d,c as a,a4 as o}from"./chunks/framework.B8PHay3u.js";const b=JSON.parse('{"title":"在线演示","description":"","frontmatter":{},"headers":[],"relativePath":"demo.md","filePath":"demo.md","lastUpdated":1790415629000}'),r={name:"demo.md"};function c(i,t,l,h,n,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h1><p>下面嵌入的是本系统网页端的完整体验环境，可直接操作。演示后端为 <a href="/Electrical-Manager/api">Apifox Mock 服务</a>：返回的是契约里的响应示例（一套华星镍业电气自动化车间业务台账）， 所有读写均为模拟数据，不影响任何真实业务数据。</p><iframe src="/Electrical-Manager/demo/" title="HXNI 电气无忧 在线演示" width="390" height="844" style="display:block;margin:16px auto;border:1px solid var(--vp-c-divider);border-radius:24px;background:#fff;box-shadow:0 6px 24px rgba(0,0,0,.08);" loading="lazy" referrerpolicy="no-referrer"></iframe><p style="text-align:center;margin-top:8px;"><a href="/Electrical-Manager/demo/" target="_blank" rel="noopener">在新窗口打开演示 ↗</a></p><h2 id="可用功能" tabindex="-1">可用功能 <a class="header-anchor" href="#可用功能" aria-label="Permalink to &quot;可用功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>登录账号</td><td><code>admin</code> / <code>warehouse</code> / <code>purchase</code> / <code>readonly</code>，密码均为 <code>123456</code>；Mock 的登录响应是固定示例，四个账号都以示例用户身份进入</td></tr><tr><td>覆盖模块</td><td>工作台、二级库物资、库存余额与流水、申购计划、申购记录、物料编码库、华星库存、周期性计划、精简库存、备忘录</td></tr><tr><td>可交互操作</td><td>新增、编辑、删除、出入库、冲销流水、筛选与分页排序；写入仅作用于 Mock 服务，刷新后恢复响应示例</td></tr><tr><td>角色差异</td><td>接真实后端时按角色区分菜单与写操作；Mock 下统一按示例用户（系统管理员）呈现</td></tr></tbody></table><p>演示为手机端比例的窗口，与系统在移动端的呈现一致；宽屏下建议点「在新窗口打开演示」。</p><h2 id="构建与发布" tabindex="-1">构建与发布 <a class="header-anchor" href="#构建与发布" aria-label="Permalink to &quot;构建与发布&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产物</th><th>构建命令</th><th>base</th><th>部署位置</th></tr></thead><tbody><tr><td>业务网页端</td><td><code>npm run build</code></td><td><code>/</code></td><td>自有服务器 / 容器镜像</td></tr><tr><td>在线演示</td><td><code>vite build --mode demo</code></td><td><code>/Electrical-Manager/demo/</code></td><td>本站在 <code>/demo/</code></td></tr></tbody></table><p>演示的构建参数在 <code>web/.env.demo</code>（子路径与 Mock 地址），后端由 <code>VITE_API_BASE_URL</code> 指向 Apifox Mock（前端不内置 Mock 层）。发布由 <code>.github/workflows/website.yml</code> 在站点构建完成后构建演示并复制到站点输出的 <code>demo/</code> 目录，因此与文档站同域，可直接 iframe 嵌入。</p><h2 id="深链刷新" tabindex="-1">深链刷新 <a class="header-anchor" href="#深链刷新" aria-label="Permalink to &quot;深链刷新&quot;">​</a></h2><p>演示使用 history 路由，静态托管本身没有 SPA fallback。这里加了一层回退，<strong>深层路由可以直接刷新</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>行为</th></tr></thead><tbody><tr><td>1</td><td>刷新 <code>/demo/warehouse/stock</code> 时静态托管找不到文件，落到站点 404 页</td></tr><tr><td>2</td><td>站点 404 页识别为演示路径，带原路径跳回演示入口（<code>?path=…</code>）</td></tr><tr><td>3</td><td>演示入口的引导脚本在路由挂载前还原真实路径，页面正常渲染</td></tr></tbody></table><p>只影响演示产物与站点 404 页：业务构建不带该标记，行为不变；路由配置未改，正常访问时 URL 也不变。</p>',14)])])}const m=e(r,[["render",c]]);export{b as __pageData,m as default};
